<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('subscriptions','view');global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$sql="SELECT a.*,c.name customer_name,p.name plan_name FROM internet_accounts a LEFT JOIN customers c ON c.id=a.customer_id AND c.tenant_id=a.tenant_id LEFT JOIN internet_plans p ON p.id=a.plan_id AND p.tenant_id=a.tenant_id WHERE a.tenant_id=? ORDER BY a.expiry_date DESC LIMIT 200";$q=$conn->prepare($sql);if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}$pageTitle='Renewals';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Renewals</h2><p>Customer service accounts available for renewal.</p><?php if(!$rows):?><p>No subscription accounts found.</p><?php else:?><div class="table-responsive"><table><thead><tr><th>Customer</th><th>Account</th><th>Plan</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer_name']??'—')?></td><td><?=e($r['username']??$r['account_number']??'—')?></td><td><?=e($r['plan_name']??'—')?></td><td><?=e($r['expiry_date']??'—')?></td><td><?=e($r['status']??'')?></td><td><a href="../payments/add.php?account_id=<?=e($r['id'])?>">Record Payment</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>